arguments.command:
ls -la /app/submission/ && find /app/submission -type l | wc -l && python3 - <<'EOF'
import os, stat
root='/app/submission'
bad=[]
for dirpath, dirnames, filenames in os.walk(root):
    for name in dirnames + filenames:
        p = os.path.join(dirpath, name)
        st = os.lstat(p)
        if stat.S_ISLNK(st.st_mode): bad.append(("symlink", p))
        elif stat.S_ISDIR(st.st_mode):
            pass
        elif stat.S_ISREG(st.st_mode):
            if st.st_nlink != 1: bad.append(("nlink=%d"%st.st_nlink, p))
        else:
            bad.append(("special %o"%st.st_mode, p))
print("problems:", bad)
tot=0; cnt=0
for dirpath, dirnames, filenames in os.walk(root):
    for f in filenames:
        p=os.path.join(dirpath,f); tot+=os.path.getsize(p); cnt+=1
print("files", cnt, "bytes", tot)
print("planner nlink", os.lstat('/app/submission/planner.py').st_nlink)
EOF
find /app/submission -name "__pycache__" -o -name "*.pyc" | head
